<template>
  <div class="product-page research-page" data-testid="research-workbench">
    <header class="page-heading"><div><h1>科研工作台</h1><p>从导入记录和处方后结局形成可复现研究资产；未冻结数据集和未审核报告不能提交知识。</p></div><div class="page-heading-actions"><el-button :icon="FileJson2" @click="flow.importDialogVisible=true">切换 JSON 场景</el-button><el-button :icon="History" @click="auditDrawer=true">流程审计</el-button></div></header>

    <el-skeleton v-if="!seed" :rows="12" animated/>
    <template v-else>
      <div class="research-link-banner"><GitMerge :size="18"/><div><strong>临床流程数据已接入科研候选池</strong><span>导入历史记录 {{ seed.historicalRecords.length }} 条 · 医生流程新增 {{ flow.completedOutcomeCount }} 条 · 当前可筛选 {{ flow.researchRecords.length }} 条</span></div><el-tag :type="flow.completedOutcomeCount?'success':'info'" effect="plain">{{ flow.completedOutcomeCount ? '存在实时新增记录' : '等待医生结局记录' }}</el-tag></div>

      <section class="research-context surface-panel"><div><span>当前项目</span><strong>{{ seed.project.title }}</strong><small>{{ seed.project.projectId }} · 负责人 {{ seed.project.owner }}</small></div><div><span>数据集版本</span><strong>{{ flow.datasetVersion || '尚未冻结' }}</strong><small>{{ flow.datasetHash || '完成质量检查后生成哈希' }}</small></div><div><span>流程进度</span><strong>{{ flow.researchProgress }} / 8</strong><small>上游变化会使下游结果失效</small></div><div><span>数据边界</span><strong>合成流程验证</strong><small>不得包装为临床或科研结论</small></div></section>

      <nav class="research-steps" aria-label="科研流程阶段"><button v-for="(step,index) in steps" :key="step.key" :class="[step.state,{active:activeStep===step.key}]" @click="activeStep=step.key"><span><CircleCheck v-if="step.state==='done'" :size="15"/><LockKeyhole v-else-if="step.state==='locked'" :size="13"/><span v-else>{{ index+1 }}</span></span><div><strong>{{ step.label }}</strong><small>{{ step.meta }}</small></div><ChevronRight v-if="index<steps.length-1" :size="15"/></button></nav>
      <el-alert v-if="actionError" type="error" :title="actionError" :closable="false" show-icon/>

      <section v-if="activeStepData?.state==='locked'" class="stage-lock surface-panel"><LockKeyhole :size="28"/><h2>{{ activeStepData.label }}尚未解锁</h2><p>{{ activeStepData.lockReason }}</p><el-button type="primary" @click="activeStep=activeStepData.previous">返回上一步</el-button></section>

      <div v-else-if="activeStep==='protocol'" class="research-grid protocol-grid">
        <section class="surface-panel"><div class="surface-panel-header"><h2>研究方案</h2><span>{{ seed.project.protocolVersion }} · {{ flow.protocolSaved?'已保存':'草稿' }}</span></div><el-form class="research-form" label-position="top"><el-form-item label="研究问题"><el-input v-model="protocolForm.researchQuestion" type="textarea" :rows="3"/></el-form-item><div class="form-two"><el-form-item label="研究设计"><el-input v-model="protocolForm.design"/></el-form-item><el-form-item label="观察时间窗"><el-input v-model="protocolForm.observationWindow"/></el-form-item></div><el-form-item label="伦理与数据边界"><el-input v-model="protocolForm.ethicsStatus" type="textarea" :rows="2"/></el-form-item><el-button type="primary" :icon="Save" :disabled="!protocolComplete" @click="saveProtocol">保存方案并锁定版本口径</el-button></el-form></section>
        <section class="surface-panel criteria-panel"><div class="surface-panel-header"><h2>纳入与排除标准</h2><span>随方案版本保存</span></div><div class="criteria-block"><h3><CirclePlus :size="15"/>纳入标准</h3><ol><li v-for="item in seed.project.inclusionCriteria" :key="item">{{ item }}</li></ol></div><div class="criteria-block exclude"><h3><CircleMinus :size="15"/>排除标准</h3><ol><li v-for="item in seed.project.exclusionCriteria" :key="item">{{ item }}</li></ol></div></section>
      </div>

      <section v-else-if="activeStep==='cohort'" class="surface-panel cohort-panel"><div class="surface-panel-header"><h2>研究队列构建</h2><div><span>{{ flow.researchRecords.length }} 条候选记录</span><el-button type="primary" size="small" :icon="Filter" @click="buildCohort">执行纳排并生成队列</el-button></div></div><div class="cohort-summary"><div><span>候选记录</span><strong>{{ flow.researchRecords.length }}</strong></div><div><span>本轮纳入</span><strong>{{ flow.cohortBuilt?flow.cohortRecordIds.length:'-' }}</strong></div><div><span>医生流程新增</span><strong>{{ flow.completedOutcomeCount }}</strong></div><div><span>排除</span><strong>{{ flow.cohortBuilt?flow.researchRecords.length-flow.cohortRecordIds.length:'-' }}</strong></div></div><table class="dense-table"><thead><tr><th>记录 / 来源</th><th>患者 / 就诊</th><th>诊断</th><th>实际暴露</th><th>结局</th><th>纳排结果</th></tr></thead><tbody><tr v-for="record in flow.researchRecords" :key="record.recordId"><td><strong>{{ record.recordId }}</strong><small>{{ record.sourceVersion }}</small></td><td><strong>{{ record.patientId }}</strong><small>{{ record.encounterId }} · {{ record.age }}岁</small></td><td>{{ record.diagnosis }}</td><td>{{ record.regimen }}</td><td>{{ responseLabel(record.treatmentResponse) }}<small>随访 {{ record.followupComplete?'完整':'缺失' }}</small></td><td><span v-if="flow.cohortBuilt" class="status-pill" :class="flow.cohortRecordIds.includes(record.recordId)?'':'info'"><span class="dot"></span>{{ flow.cohortRecordIds.includes(record.recordId)?'纳入':'排除' }}</span><span v-else>待执行</span></td></tr></tbody></table></section>

      <section v-else-if="activeStep==='variables'" class="surface-panel"><div class="surface-panel-header"><h2>变量字典</h2><div><span>{{ seed.variables.length }} 个版本化变量</span><el-button type="primary" size="small" :icon="CheckCircle2" @click="confirmVariables">确认变量口径</el-button></div></div><table class="dense-table variable-table"><thead><tr><th>变量</th><th>角色</th><th>类型</th><th>统一模型路径</th><th>缺失处理</th></tr></thead><tbody><tr v-for="variable in seed.variables" :key="variable.code"><td><strong>{{ variable.name }}</strong><small>{{ variable.code }}</small></td><td><span class="variable-role">{{ variableRoleLabel(variable.role) }}</span></td><td>{{ variable.type }}</td><td><code>{{ variable.sourcePath }}</code></td><td>{{ variable.missingRule }}</td></tr></tbody></table></section>

      <div v-else-if="activeStep==='quality'" class="research-grid quality-grid">
        <section class="surface-panel"><div class="surface-panel-header"><h2>数据质量与冻结门槛</h2><span>{{ flow.includedRecords.length }} 条纳入记录</span></div><div class="quality-metrics"><div><span>样本量</span><strong>{{ flow.includedRecords.length }}</strong><small>来自当前纳排版本</small></div><div><span>随访完整率</span><strong>{{ followupRate }}%</strong><small>缺失必须披露</small></div><div><span>不良事件记录</span><strong>{{ adverseCount }}</strong><small>仅描述，不推断因果</small></div><div><span>未解决问题</span><strong>{{ flow.unresolvedQualityIssues.length }}</strong><small>阻断问题必须清零</small></div></div><div class="freeze-action"><div><strong>冻结分析数据集</strong><span>冻结后生成版本和输入哈希；任何上游变化都会使结果失效。</span></div><el-button type="primary" :icon="Snowflake" :disabled="hasBlockingQuality" @click="freezeDataset">{{ flow.datasetVersion?'重新冻结数据集':'冻结数据集版本' }}</el-button></div><div v-if="flow.datasetVersion" class="dataset-receipt"><FileLock2 :size="18"/><div><strong>{{ flow.datasetVersion }}</strong><span>输入哈希 {{ flow.datasetHash }} · {{ flow.includedRecords.length }} 条记录</span></div><el-tag type="success">已冻结</el-tag></div></section>
        <section class="surface-panel issue-panel"><div class="surface-panel-header"><h2>质量问题队列</h2><span>{{ flow.resolvedQualityIssues.length }} / {{ seed.qualityIssues.length }} 已处理</span></div><div class="quality-issues"><article v-for="issue in seed.qualityIssues" :key="issue.issueId" :class="{resolved:flow.resolvedQualityIssues.includes(issue.issueId)}"><header><span class="status-pill" :class="issue.severity==='blocking'?'danger':'warning'"><span class="dot"></span>{{ issue.severity==='blocking'?'阻断':'警告' }}</span><code>{{ issue.issueId }}</code></header><strong>{{ issue.title }}</strong><p>{{ issue.field }} · 影响 {{ issue.affectedRecords }} 条</p><small>处理口径：{{ issue.resolution }}</small><el-button size="small" :type="issue.severity==='blocking'?'danger':'primary'" plain :disabled="flow.resolvedQualityIssues.includes(issue.issueId)" @click="resolveIssue(issue.issueId)">{{ flow.resolvedQualityIssues.includes(issue.issueId)?'已记录处理':'记录处理结果' }}</el-button></article></div></section>
      </div>

      <div v-else-if="activeStep==='analysis'" class="research-grid analysis-grid"><section class="surface-panel"><div class="surface-panel-header"><h2>固定统计计划</h2><span>{{ seed.analysisPlan.scriptName }} v{{ seed.analysisPlan.scriptVersion }}</span></div><div class="analysis-body"><div class="analysis-version"><Code2 :size="20"/><div><strong>{{ seed.analysisPlan.method }}</strong><span>{{ flow.datasetVersion }} · 输入 {{ flow.datasetHash }}</span></div><span class="status-pill"><span class="dot"></span>方法已固定</span></div><h3>预定义输出</h3><ul class="analysis-outputs"><li v-for="output in seed.analysisPlan.outputs" :key="output"><Table2 :size="14"/>{{ output }}</li></ul><el-button type="primary" :icon="Play" :loading="flow.analysisStatus==='running'" @click="runAnalysis">运行固定版本统计</el-button></div></section><section class="surface-panel"><div class="surface-panel-header"><h2>分析结果</h2><span>{{ flow.analysisResult?.runId || '尚未运行' }}</span></div><div v-if="flow.analysisResult" class="analysis-results"><div><span>样本量</span><strong>{{ flow.analysisResult.sampleSize }}</strong></div><div><span>改善</span><strong>{{ flow.analysisResult.improvedCount }}</strong></div><div><span>不良事件</span><strong>{{ flow.analysisResult.adverseEventCount }}</strong></div><div><span>随访缺失</span><strong>{{ flow.analysisResult.followupMissingCount }}</strong></div><section><h3>方案暴露分布</h3><p v-for="item in flow.analysisResult.regimenDistribution" :key="item.regimen"><span>{{ item.regimen }}</span><strong>{{ item.count }}</strong></p></section><footer>输出哈希 <code>{{ flow.analysisResult.outputHash }}</code></footer></div><div v-else class="empty-stage"><BarChart3 :size="28"/><p>运行后显示由固定代码产生的描述性结果和输出哈希。</p></div></section></div>

      <div v-else-if="activeStep==='report'" class="report-workspace"><section class="surface-panel report-outline"><div class="surface-panel-header"><h2>报告版本</h2><span>{{ flow.reportVersion || '尚未生成' }}</span></div><button v-for="section in reportSectionDefs" :key="section.key" :class="{active:reportSection===section.key}" @click="reportSection=section.key"><component :is="section.icon" :size="15"/><span><strong>{{ section.label }}</strong><small>{{ flow.reportSections[section.key]?'已生成':'等待统计结果' }}</small></span></button><div class="report-actions"><el-button type="primary" :icon="WandSparkles" @click="generateReport">{{ flow.reportStatus==='not_started'?'生成报告草稿':'重新生成草稿' }}</el-button><el-button :icon="Send" :disabled="flow.reportStatus!=='draft'" @click="submitReport">提交审核</el-button></div></section><section class="surface-panel report-editor"><div class="surface-panel-header"><h2>{{ currentReportSection.label }}</h2><span>AI 草稿与事实数据分开保存</span></div><div v-if="flow.reportStatus!=='not_started'" class="report-editor-body"><el-alert type="warning" title="这是可编辑报告草稿，不是可直接投稿论文，也不会自动成为临床知识。" :closable="false" show-icon/><el-input v-model="flow.reportSections[reportSection]" type="textarea" :rows="15" @change="flow.persist()"/><footer><span>数据集 {{ flow.datasetVersion }} · 运行 {{ flow.analysisResult?.runId }}</span><el-tag :type="flow.reportStatus==='in_review'?'warning':'info'">{{ reportStatusLabel }}</el-tag></footer></div><div v-else class="empty-stage"><FileText :size="28"/><p>先生成报告草稿，系统会绑定数据集、统计运行和限制说明。</p></div></section></div>

      <div v-else-if="activeStep==='freeze'" class="research-grid review-grid"><section class="surface-panel"><div class="surface-panel-header"><h2>审核清单</h2><span>{{ flow.reportVersion }}</span></div><div class="review-checks"><label v-for="item in reviewChecklist" :key="item"><el-checkbox v-model="reviewChecks[item]"/>{{ item }}</label></div><div class="review-note"><strong>审核意见</strong><el-input v-model="reviewNote" type="textarea" :rows="3" placeholder="说明统计方法、结论边界和发布限制"/></div><el-button type="primary" :icon="FileLock2" :disabled="!allReviewChecked||!reviewNote.trim()" @click="approveReport">批准并冻结报告版本</el-button></section><section class="surface-panel lineage-panel"><div class="surface-panel-header"><h2>版本血缘</h2><span>不可覆盖旧版本</span></div><ol><li><Database :size="15"/><div><strong>{{ flow.datasetVersion }}</strong><small>{{ flow.datasetHash }}</small></div></li><li><Code2 :size="15"/><div><strong>{{ flow.analysisResult?.runId }}</strong><small>{{ flow.analysisResult?.outputHash }}</small></div></li><li><FileText :size="15"/><div><strong>{{ flow.reportVersion }}</strong><small>{{ reportStatusLabel }}</small></div></li></ol></section></div>

      <div v-else-if="activeStep==='knowledge'" class="knowledge-submit surface-panel"><BookOpenCheck :size="30"/><h2>提交知识审核</h2><p>仅提交已审核冻结的报告候选；知识内容在药师与研究负责人分别批准前不会参与正式推荐。</p><dl><div><dt>数据集</dt><dd>{{ flow.datasetVersion }} · n={{ flow.analysisResult?.sampleSize }}</dd></div><div><dt>分析运行</dt><dd>{{ flow.analysisResult?.runId }} · {{ flow.analysisResult?.outputHash }}</dd></div><div><dt>报告</dt><dd>{{ flow.reportVersion }} · 已审核冻结</dd></div><div><dt>适用范围</dt><dd>{{ seed.reportTemplate.applicability }}</dd></div></dl><div class="knowledge-actions"><el-button type="primary" :icon="Send" :disabled="flow.knowledgeStatus==='review_pending'" @click="submitKnowledge">{{ flow.knowledgeStatus==='review_pending'?'已提交，等待双角色审核':'提交知识审核中心' }}</el-button><el-button v-if="flow.knowledgeStatus==='review_pending'" :icon="BookOpenCheck" @click="router.push('/knowledge/reviews')">查看知识审核任务</el-button></div><el-alert v-if="flow.knowledgeStatus==='review_pending'" type="success" title="知识候选已进入 review_pending，不会参与当前处方推荐。" :closable="false" show-icon/></div>
    </template>

    <el-drawer v-model="auditDrawer" title="前端流程审计" size="480px"><div class="flow-audit"><article v-for="event in flow.auditEvents" :key="event.eventId"><span></span><div><strong>{{ event.action }}</strong><p>{{ event.detail }}</p><small>{{ formatTime(event.occurredAt) }} · {{ event.eventId }}</small></div></article></div></el-drawer>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { BarChart3, BookOpenCheck, CheckCircle2, ChevronRight, CircleCheck, CircleMinus, CirclePlus, Code2, Database, FileJson2, FileLock2, FileText, Filter, GitMerge, History, LockKeyhole, Play, Save, Send, Snowflake, Table2, WandSparkles } from 'lucide-vue-next'
import { useFlowSimulationStore } from '../stores/flowSimulation'
import type { ResearchRecord, ResearchVariable } from '../types/flowScenario'

const flow=useFlowSimulationStore();const router=useRouter();const activeStep=ref('protocol');const actionError=ref('');const auditDrawer=ref(false);const reportSection=ref('question');const reviewNote=ref('已核对数据集版本、统计方法、缺失说明和结论适用边界。')
const protocolForm=reactive({researchQuestion:'',design:'',observationWindow:'',ethicsStatus:''})
const reviewChecklist=['数据集版本与纳排记录一致','统计脚本版本和输入输出哈希完整','缺失数据与异常处理已经披露','AI 草稿未越过描述性结果边界','适用范围与不适用范围已明确']
const reviewChecks=reactive<Record<string,boolean>>(Object.fromEntries(reviewChecklist.map(item=>[item,false])))
const seed=computed(()=>flow.scenario?.research)
const protocolComplete=computed(()=>Object.values(protocolForm).every(value=>value.trim().length>4))
const followupRate=computed(()=>flow.includedRecords.length?((flow.includedRecords.filter(item=>item.followupComplete).length/flow.includedRecords.length)*100).toFixed(1):'0.0')
const adverseCount=computed(()=>flow.includedRecords.filter(item=>item.adverseEvent).length)
const hasBlockingQuality=computed(()=>flow.unresolvedQualityIssues.some(item=>item.severity==='blocking'))
const allReviewChecked=computed(()=>reviewChecklist.every(item=>reviewChecks[item]))
const reportStatusLabel=computed(()=>({not_started:'尚未生成',draft:'报告草稿',in_review:'审核中',approved_frozen:'已审核冻结'} as const)[flow.reportStatus])
const reportSectionDefs=[{key:'question',label:'研究问题与设计',icon:FileText},{key:'cohort',label:'纳入排除与基线',icon:Filter},{key:'exposure',label:'用药暴露',icon:Database},{key:'outcomes',label:'结局与安全性',icon:BarChart3},{key:'limitations',label:'缺失、偏倚与限制',icon:LockKeyhole},{key:'conclusion',label:'AI 结论草稿',icon:WandSparkles}]
const currentReportSection=computed(()=>reportSectionDefs.find(item=>item.key===reportSection.value)??reportSectionDefs[0])
const steps=computed(()=>[
  {key:'protocol',label:'研究方案',meta:flow.protocolSaved?'版本已保存':'待保存',state:flow.protocolSaved?'done':'active',previous:'protocol',lockReason:''},
  {key:'cohort',label:'研究队列',meta:flow.cohortBuilt?`${flow.cohortRecordIds.length} 条`:'待纳排',state:!flow.protocolSaved?'locked':flow.cohortBuilt?'done':'ready',previous:'protocol',lockReason:'先保存研究方案与纳排口径。'},
  {key:'variables',label:'变量字典',meta:flow.variablesConfirmed?`${seed.value?.variables.length??0} 个已确认`:'待确认',state:!flow.cohortBuilt?'locked':flow.variablesConfirmed?'done':'ready',previous:'cohort',lockReason:'先执行纳排并生成研究队列。'},
  {key:'quality',label:'数据质量',meta:flow.datasetVersion?'数据集已冻结':`${flow.unresolvedQualityIssues.length} 项待处理`,state:!flow.variablesConfirmed?'locked':flow.datasetVersion?'done':'ready',previous:'variables',lockReason:'先确认变量、来源路径和缺失处理口径。'},
  {key:'analysis',label:'统计分析',meta:flow.analysisStatus==='succeeded'?'运行成功':flow.analysisStatus==='running'?'运行中':'待运行',state:!flow.datasetVersion?'locked':flow.analysisStatus==='succeeded'?'done':'ready',previous:'quality',lockReason:'先处理阻断级质量问题并冻结数据集版本。'},
  {key:'report',label:'报告草稿',meta:flow.reportVersion||'待生成',state:flow.analysisStatus!=='succeeded'?'locked':flow.reportStatus!=='not_started'?'done':'ready',previous:'analysis',lockReason:'固定版本统计成功后才能生成报告草稿。'},
  {key:'freeze',label:'审核冻结',meta:flow.reportStatus==='approved_frozen'?'已冻结':flow.reportStatus==='in_review'?'待审核':'未提交',state:flow.reportStatus!=='in_review'&&flow.reportStatus!=='approved_frozen'?'locked':flow.reportStatus==='approved_frozen'?'done':'ready',previous:'report',lockReason:'报告草稿必须先提交审核。'},
  {key:'knowledge',label:'知识提交',meta:flow.knowledgeStatus==='review_pending'?'审核中':'尚未提交',state:flow.reportStatus!=='approved_frozen'?'locked':flow.knowledgeStatus==='review_pending'?'done':'ready',previous:'freeze',lockReason:'只有已审核冻结的报告才能提交知识候选。'}
])
const activeStepData=computed(()=>steps.value.find(step=>step.key===activeStep.value))

function runAction(action:()=>void,next?:string){actionError.value='';try{action();if(next)activeStep.value=next}catch(error){actionError.value=error instanceof Error?error.message:'流程操作失败'}}
function saveProtocol(){if(seed.value){Object.assign(seed.value.project,protocolForm)}runAction(()=>flow.saveProtocol(),'cohort')}
function buildCohort(){runAction(()=>flow.buildCohort(),'variables')}
function confirmVariables(){runAction(()=>flow.confirmVariables(),'quality')}
function resolveIssue(id:string){runAction(()=>flow.resolveQualityIssue(id))}
function freezeDataset(){runAction(()=>flow.freezeDataset(),'analysis')}
async function runAnalysis(){actionError.value='';try{await flow.runAnalysis();activeStep.value='report'}catch(error){actionError.value=error instanceof Error?error.message:'统计任务失败'}}
function generateReport(){runAction(()=>flow.generateReport())}
function submitReport(){runAction(()=>flow.submitReportReview(),'freeze')}
function approveReport(){runAction(()=>flow.approveAndFreezeReport(),'knowledge')}
function submitKnowledge(){runAction(()=>flow.submitKnowledge())}
function responseLabel(value:ResearchRecord['treatmentResponse']){return({improved:'改善',stable:'稳定',worsened:'恶化',unknown:'未知'} as const)[value]}
function variableRoleLabel(value:ResearchVariable['role']){return({exposure:'暴露',outcome:'结局',group:'分组',confounder:'混杂因素'} as const)[value]}
function formatTime(value:string){return new Date(value).toLocaleString('zh-CN',{hour12:false})}

watch(()=>flow.revision,(revision,previous)=>{if(!previous||!revision||!seed.value)return;Object.assign(protocolForm,{researchQuestion:seed.value.project.researchQuestion,design:seed.value.project.design,observationWindow:seed.value.project.observationWindow,ethicsStatus:seed.value.project.ethicsStatus});activeStep.value='protocol';actionError.value=''})

onMounted(async()=>{await flow.ensureScenario();if(seed.value)Object.assign(protocolForm,{researchQuestion:seed.value.project.researchQuestion,design:seed.value.project.design,observationWindow:seed.value.project.observationWindow,ethicsStatus:seed.value.project.ethicsStatus})})
